// Main render loop. Brick collision is resolved here (still entangled with
// rendering — debt #2), but the geometry itself lives in brickEntry() /
// resolveBrickCollision() so it is testable and correct (#1).
export function frame(ctx, state) {
  const { ball } = state;

  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: detect every brick the ball crossed this frame (swept segment), so
  // a fast ball cannot tunnel through; score and destroy them all, then apply
  // exactly ONE bounce against the first-contact group (a ball straddling an
  // 8 px seam overlaps two bricks in the same pass — the flip must not happen
  // twice).
  let first = Infinity;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const t = brickEntry(ball, brick);
    if (t !== null && t < first) first = t;
  }
  const hits = [];
  if (first !== Infinity) {
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const t = brickEntry(ball, brick);
      if (t !== null && Math.abs(t - first) <= 1e-9) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
        hits.push(brick);
      }
    }
  }
  resolveBrickCollision(ball, hits);

  // Draw the surviving bricks.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
